random.seed(1234)
class TestIsHex(unittest.TestCase):
    def test_fuzz(self):
        for _ in range(500):
            s = ''.join(random.choices('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789', k=random.randint(1, 10)))
            assert not is_hex(s) if any(c not in '0123456789abcdefABCDEF' for c in s) else is_hex(s)
if __name__ == '__main__': unittest.main()

